// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    // We'll fuzz: address from, address[] tos encoded via bytes seed, and uint[] values via uint seed.
    // Solidity/Foundry fuzz cannot directly pass dynamic arrays as params to the test entry easily in all setups,
    // so we take fuzzed uint256 seeds and derive small arrays from them to keep the test general.
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, address calleeAddr, uint256 seed1, uint256 seed2) public {
        // Keep addresses wide but avoid zero-address for 'calleeAddr' because we will deploy a helper and use its address.
        vm.assume(from != address(0));
        // Deploy a recording helper that implements transferFrom(address,address,uint256)
        // It will record the last call and increment a counter. The reference contract will call it inside the loop.
        Recorder r = new Recorder();

        // Construct small arrays for tos and v from seeds so the fuzz explores many combinations,
        // while ensuring _tos.length > 0 as required by C.transfer.
        uint len = 1 + (seed1 % 4); // length in 1..4
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            // derive addresses and values from seeds and index
            tos[i] = address(uint160(uint(keccak256(abi.encodePacked(seed1, i, calleeAddr)))));
            vals[i] = uint(keccak256(abi.encodePacked(seed2, i, from))) % 1000; // keep amounts small but varied
        }

        // We will pass the address of our recorder so that c.call(...) invokes its transferFrom and succeeds.
        // The GENERAL RULE: when transfer completes (does not revert), it returns true.
        bool ok;
        try c.transfer(from, address(r), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: for ALL admissible inputs where the call does not revert, the correct contract returns true.
        // Thus ok must be true (transfer should complete). We assert this fact; the mutant that returns false will
        // cause the test to fail because try/catch does not catch a returned false — so we also check the actual return value
        // by calling via a low-level staticcall wrapper to observe the returned boolean without changing state.

        // Prepare calldata for transfer and perform a low-level call to read the returned bool (works because function is non-view but doesn't need state change detection here)
        // We perform the call from this test contract (no special msg.sender) to read the returned data.
        bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("transfer(address,address,address[],uint256[])")), from, address(r), tos, vals);
        (bool success, bytes memory ret) = address(c).call(payload);

        // success must match ok from try/catch (both indicate no revert)
        assertTrue(success == ok);

        // If the call succeeded, the reference contract always returns true, so when success==true the returned data must decode to true.
        if (success) {
            // decode return value
            bool returned = abi.decode(ret, (bool));
            assertTrue(returned == true);
        } else {
            // If it reverted, nothing further to assert about return value; but the reference contract should not revert given our recorder succeeds.
            // Keep wide: no extra assumptions here.
        }
    }
}

// Recorder: matches the selector transferFrom(address,address,uint256) and records calls
contract Recorder {
    uint public callCount;
    address[] public froms;
    address[] public tos;
    uint[] public vals;

    // function signature must match what C encodes: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        callCount += 1;
        froms.push(from);
        tos.push(to);
        vals.push(value);
        return true; // behave well (succeed) so reference contract proceeds and returns true
    }
}
